+fn fmt(src:&str)->String{ crate::parse::parse_format::<sway_ast::ItemKind>(src, sway_features::ExperimentalFeatures::default()).unwrap() }
+
+#[test]
+fn repro_idem() {
+    let cases = [
+// two separate comment groups; first has multibyte unicode
+"impl A for B {
+    fn foo() {
+        let a = 1;
+        // 日本語日本語 unicode comment
+        let b = 2;
+        // second ascii comment
+        let c = 3;
+        d
+    }
+}",
+    ];
+    for (i,src) in cases.iter().enumerate() {
+        let f1 = fmt(src);
+        let f2 = fmt(&f1);
+        println!("=== CASE {i} FIRST ===\n{f1}\n=== END ===");
+        if &f1 != src { println!("!!! CASE {i} first pass CHANGED already-formatted input"); }
+        if f1 != f2 { println!("!!! CASE {i} NOT idempotent\n--- SECOND ---\n{f2}\n---"); }
+    }
+}
