+fn fmt(src:&str)->String{ crate::parse::parse_format::<sway_ast::ItemKind>(src, sway_features::ExperimentalFeatures::default()).unwrap() }
+
+#[test]
+fn repro_comprehensive() {
+    // Already-correctly-formatted; must be returned identically (idempotent) on both passes.
+    let good =
+"impl AuthTesting for Contract {
+    fn returns_msg_sender(expected_id: ContractId) -> bool {
